const createNode = () => ({ files: [], tokenSum: 0, children: new Map() });
export const buildTokenCountTree = (filesWithTokens) => {
    const root = createNode();
    for (const file of filesWithTokens) {
        if (!file.path || typeof file.path !== 'string') {
            continue;
        }
        const parts = file.path.split('/');
        const fileName = parts.pop();
        if (!fileName)
            continue;
        let current = root;
        for (const part of parts) {
            let child = current.children.get(part);
            if (!child) {
                child = createNode();
                current.children.set(part, child);
            }
            current = child;
        }
        current.files.push({
            name: fileName,
            tokens: file.tokens,
        });
    }
    calculateTokenSums(root);
    return root;
};
const calculateTokenSums = (node) => {
    let totalTokens = node.files.reduce((sum, file) => sum + file.tokens, 0);
    for (const child of node.children.values()) {
        totalTokens += calculateTokenSums(child);
    }
    node.tokenSum = totalTokens;
    return totalTokens;
};
